import java.util.ArrayList;
import java.util.List;

public class ArrayListResizeDemo {
    public static void main(String[] args) {
        // Default initial capacity is 10
        List<String> orders = new ArrayList<>();

        // Add 10 elements - no resize yet
        for (int i = 1; i <= 10; i++) orders.add("Order-" + i);

        // 11th element triggers resize: 10 -> 15 (10 + 10/2)
        orders.add("Order-11");

        // Fill to 15 - no resize
        for (int i = 12; i <= 15; i++) orders.add("Order-" + i);

        // 16th element triggers resize: 15 -> 22 (15 + 15/2)
        orders.add("Order-16");

        // If you know the size upfront, pre-size to avoid resizes
        List<String> bulk = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) bulk.add("Order-" + i); // no resizes
    }
}
