import java.util.Deque;
import java.util.LinkedList;

public class LinkedListDequeDemo {
    public static void main(String[] args) {
        // FIFO queue
        Deque<String> orderQueue = new LinkedList<>();
        orderQueue.addLast("Order-101");          // O(1) enqueue at tail
        orderQueue.addLast("Order-102");
        String processed = orderQueue.removeFirst(); // O(1) dequeue at head

        // LIFO stack
        Deque<String> undoStack = new LinkedList<>();
        undoStack.addFirst("Action-1");           // O(1) push at front
        undoStack.addFirst("Action-2");
        String lastAction = undoStack.removeFirst(); // O(1) pop at front

        // Double-ended queue
        Deque<String> taskDeque = new LinkedList<>();
        taskDeque.addFirst("High-priority");      // urgent at front
        taskDeque.addLast("Low-priority");         // regular at back
        String urgent = taskDeque.removeFirst();
        String regular = taskDeque.removeLast();
    }
}
