import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

public class VectorReplacementDemo {
    public static void main(String[] args) {
        // Legacy: Vector (synchronized, avoid in new code)
        Vector<String> legacy = new Vector<>();
        legacy.add("Order-1");                  // acquires a lock

        // Modern single-threaded: ArrayList
        List<String> orders = new ArrayList<>();
        orders.add("Order-1");                   // no lock overhead

        // Multi-threaded basic: synchronizedList (still needs external lock for compound ops)
        List<String> sync = Collections.synchronizedList(new ArrayList<>());
        synchronized (sync) {
            if (!sync.isEmpty()) {
                String first = sync.get(0);      // safe inside the block
            }
        }

        // Read-heavy concurrent: CopyOnWriteArrayList
        List<String> concurrent = new CopyOnWriteArrayList<>();
        concurrent.add("Order-1");               // locks only for the write
        String read = concurrent.get(0);         // reads never block
    }
}
