import java.util.ArrayList;
import java.util.List;

public class ArrayListComplexityDemo {
    public static void main(String[] args) {
        List<String> orders = new ArrayList<>();
        orders.add("Order-1");          // amortized O(1) - write to next slot
        orders.add("Order-2");
        orders.add("Order-3");

        String second = orders.get(1);  // O(1) - direct array access

        orders.add(1, "Order-1.5");     // O(n) - shift later elements right
        // [Order-1, Order-1.5, Order-2, Order-3]

        orders.remove(1);               // O(n) - shift later elements left
        // [Order-1, Order-2, Order-3]

        boolean found = orders.contains("Order-2"); // O(n) - linear scan
        int index = orders.indexOf("Order-3");      // O(n) worst case
    }
}
```

